/* Equal specificity — the LATER rule wins */
p { color: red; }
p { color: blue; }  /* ← this wins — blue text */

/* Order of <link> tags in HTML also matters */
/* Second stylesheet overrides first for equal specificity */

/* Set font on the parent — all children inherit it */
body {
  font-family: Inter, sans-serif;
  color: #e2e8f0;
}

/* Explicitly inherit or reset */
button { font-family: inherit; }  /* buttons don't inherit by default */
a      { color: inherit; }        /* links default to blue — override it */

/* !important beats ALL other declarations for that property */
p { color: blue !important; }  /* this wins, regardless of specificity */
#hero p { color: red; }        /* even this loses to !important above */

/* Use !important only for:
   - Overriding third-party library styles you cannot touch
   - Utility classes that must always win (.hidden { display: none !important; }) */
